-- 034_session_opening.sql — MYT-101
--
-- The prep-generated session opening: player-facing DM introduction prose,
-- generated by the session-prep stage (tripwire-vetted before persist) and
-- delivered deterministically by POST /start as the session's first dm_text
-- row. Nullable: prep rows written before MYT-101 have no opening — /start
-- fails soft (silent session start + WARN), mirroring its missing-prep arm.

ALTER TABLE session_preps ADD COLUMN opening TEXT;
